"""Prototype: consistency proof for the duplicate-last-node Merkle tree."""
import hashlib, json

def sha(*parts):
    d = hashlib.sha256()
    for p in parts:
        d.update(p)
    return d.hexdigest()

def nh(l, r):
    return sha(b"\x01", l.encode(), r.encode())

def mroot(leaves):
    if not leaves:
        return "0"*64
    level = list(leaves)
    while len(level) > 1:
        if len(level) % 2:
            level.append(level[-1])
        level = [nh(level[i], level[i+1]) for i in range(0, len(level), 2)]
    return level[0]

HEX64 = set("0123456789abcdef")
ZERO = "0"*64

def expected_steps(m, n):
    """Deterministic list of proof entries ('L'/'R') derived from sizes alone."""
    if m == n or m == 0:
        return []
    steps = [("L", "seed")]
    b, w, ci = m, n, (m-1 if m % 2 else m)
    old_active_family_odd = (m % 2 == 1)
    while w > 1:
        if ci % 2 == 0:
            sib = ci + 1
            if sib < w:
                steps.append(("R", f"lvl w={w}"))
            else:
                # implicit duplicate, no proof node
                pass
        else:
            steps.append(("L", f"lvl w={w} b={b}"))
        # advance both trees one level
        b = (b + 1) // 2
        w = (w + 1) // 2
        ci //= 2
    return steps

def gen(leaves, m, n):
    if m == n or m == 0:
        return []
    proof = []
    level = list(leaves[:n])
    b, w = m, n
    ci = m-1 if m % 2 else m
    # seed
    proof.append(("L", level[m-1] if m % 2 else level[m]))
    while w > 1:
        if ci % 2 == 0:
            sib = ci + 1
            if sib < w:
                proof.append(("R", level[sib]))
            # else implicit dup
        else:
            proof.append(("L", level[ci-1]))
        # pair level (new tree) with duplication
        if len(level) % 2:
            level.append(level[-1])
        level = [nh(level[i], level[i+1]) for i in range(0, len(level), 2)]
        b = (b+1)//2
        w = (w+1)//2
        ci //= 2
    return proof

def verify(m, n, old_root, new_root, proof):
    if not all(isinstance(v, int) and not isinstance(v, bool) for v in (m, n)):
        return False
    if m < 0 or n < 0 or m > n:
        return False
    if not isinstance(old_root, str) or not isinstance(new_root, str):
        return False
    if not isinstance(proof, list):
        return False
    def ok_hash(h):
        return isinstance(h, str) and len(h) == 64 and all(c in HEX64 for c in h)
    if not ok_hash(old_root) or not ok_hash(new_root):
        return False
    if m == n:
        return proof == [] and old_root == new_root
    if m == 0:
        return proof == [] and old_root == ZERO
    for step in proof:
        if not isinstance(step, dict):
            return False
        if step.get("position") not in ("left", "right"):
            return False
        if not ok_hash(step.get("hash")):
            return False
        if set(step) != {"position", "hash"}:
            return False

    i = 0
    def take(pos):
        nonlocal i
        if i >= len(proof):
            return None
        step = proof[i]
        if step["position"] != pos:
            return False
        i += 1
        return step["hash"]

    b, w = m, n
    ci = m-1 if m % 2 else m
    h = take("L")
    if h is None or h is False:
        return False
    cur_new = h
    # old family
    if m % 2 == 1:
        cur_old = h if b == 1 else nh(h, h)
        if b == 1:
            if cur_old != old_root:
                return False
    else:
        cur_old = None

    while w > 1:
        if ci % 2 == 0:
            sib = ci + 1
            if sib < w:
                y = take("R")
                if y is None or y is False:
                    return False
                cur_new = nh(cur_new, y)
            else:
                # implicit dup (w odd)
                if w % 2 == 0:
                    return False
                cur_new = nh(cur_new, cur_new)
            if cur_old is not None and b > 1:
                # old family odd: right steps at odd old width -> old duplicates
                cur_old = nh(cur_old, cur_old)
        else:
            x = take("L")
            if x is None or x is False:
                return False
            cur_new = nh(x, cur_new)
            if b == 1:
                if cur_old is not None:
                    return False  # already attached
                if x != old_root:
                    return False
                cur_old = x
            else:
                if cur_old is None:
                    cur_old = nh(x, x)
                else:
                    cur_old = nh(x, cur_old)
        b = (b+1)//2
        w = (w+1)//2
        ci //= 2

    if i != len(proof):
        return False
    if cur_old != old_root:
        return False
    return cur_new == new_root

# exhaustive
fails = []
N = 400
leaves = [sha(b"leaf", str(i).encode()) for i in range(N)]
for n in range(0, N+1):
    rn = mroot(leaves[:n])
    for m in range(0, n+1):
        rm = mroot(leaves[:m])
        p = gen(leaves, m, n)
        pobj = [{"position": po, "hash": h} for po, h in p]
        # expected steps agreement
        exp = expected_steps(m, n)
        got = [(po, "") for po, _ in p]
        if [e[0] for e in exp] != [g[0] for g in got]:
            fails.append(("steps", m, n))
        if not verify(m, n, rm, rn, pobj):
            fails.append(("verify-false", m, n, p))
        # wrong roots must fail
        if verify(m, n, rm, sha(b"x", rn.encode()), pobj):
            fails.append(("bad-newroot", m, n))
        if m > 0 and verify(m, n, sha(b"x", rm.encode()), rn, pobj):
            fails.append(("bad-oldroot", m, n))
        # tamper each node
        for k in range(len(pobj)):
            broken = [dict(s) for s in pobj]
            broken[k]["hash"] = "e"*64
            if verify(m, n, rm, rn, broken):
                fails.append(("tamper-ok", m, n, k))
            swapped = [dict(s) for s in pobj]
            swapped[k]["position"] = "left" if swapped[k]["position"] == "right" else "right"
            if verify(m, n, rm, rn, swapped):
                fails.append(("swap-ok", m, n, k))
        # reversed order
        if pobj and verify(m, n, rm, rn, list(reversed(pobj))):
            fails.append(("reverse-ok", m, n))
        # extra / missing
        if pobj:
            if verify(m, n, rm, rn, pobj + [{"position": "left", "hash": "1"*64}]):
                fails.append(("extra-ok", m, n))
            if verify(m, n, rm, rn, pobj[:-1]):
                fails.append(("missing-ok", m, n))

# edge / format checks
edge_bad = [
    (0, 1, ZERO, mroot(leaves[:1]), [{"position":"left","hash":"1"*64}]),  # m=0 proof must be empty
    (1, 1, "a"*64, "a"*64, []),  # m=n roots equal but bogus -> accepted? semantic equality yes; skip
]
if not verify(0, 5, ZERO, mroot(leaves[:5]), []):
    fails.append("m0-empty")
if not verify(0, 0, ZERO, ZERO, []):
    fails.append("m0n0")
if verify(0, 5, "1"*64, mroot(leaves[:5]), []):
    fails.append("m0-badold")
if verify(2, 5, mroot(leaves[:2]), mroot(leaves[:5]), "notalist"):
    fails.append("proof-not-list")
if verify(2, 5, mroot(leaves[:2]), mroot(leaves[:5]), [{"position":"left","hash":"z"*64}]):
    fails.append("bad-hex")
if verify(2, 5, mroot(leaves[:2]), mroot(leaves[:5]), [{"position":"up","hash":"1"*64}]):
    fails.append("bad-pos")
if verify(-1, 5, ZERO, mroot(leaves[:5]), []):
    fails.append("neg-m")
if verify(5, 2, ZERO, ZERO, []):
    fails.append("m>n")
if verify(True, 2, ZERO, ZERO, []):
    fails.append("bool")
if verify(2, 5, mroot(leaves[:2]), mroot(leaves[:5]), [{"position":"left","hash":"1"*64, "extra":1}]):
    fails.append("extra-key")
if verify(2, 5, mroot(leaves[:2]), "A"*64, []):
    fails.append("upper-root")

print("fails:", fails[:20], "total", len(fails))

